def aprovar_documentos_ja_aceitos(apps, schema_editor):
    """Antes da revisão por documento, homologar a inscrição (ou aprovar o convite)
    aceitava todos os documentos: eles passam a constar como aprovados."""
    Documento = apps.get_model("inscricoes", "Documento")
    for documento in Documento.objects.select_related("inscricao", "convite"):
        if documento.inscricao and documento.inscricao.status == "HOMOLOGADA":
            origem = documento.inscricao
        elif documento.convite and documento.convite.status == "APROVADO":
            origem = documento.convite
        else:
            continue
        documento.decisao = "APROVADO"
        documento.decidido_por_id = origem.responsavel_decisao_id
        documento.decidido_em = origem.data_decisao or timezone.now()
        documento.save(update_fields=["decisao", "decidido_por", "decidido_em"])


